import smbus2 as smbus
import time
from typing import List, Callable

# Constants for ADS1115
ADS1115_I2C_ADDR = 0x48  # Default I2C address (ADDR pin tied to GND)
ADS1115_CONFIG_REGISTER = 0x01
ADS1115_CONVERSION_REGISTER = 0x00

# Configuration Register Bit Masks and Values (See datasheet for details)
CONFIG_OS_START = 0x8000
CONFIG_OS_PERFORMING_CONVERSION = 0x0000
CONFIG_MUX_AIN0P_GNDN = 0x4000
CONFIG_FSR_4V096 = 0x0200
CONFIG_MODE_SINGLE_SHOT = 0x0100
CONFIG_DATA_RATE_128SPS = 0x0080
CONFIG_COMP_MODE_TRADITIONAL = 0x0000
CONFIG_COMP_POL_ACTIVE_LOW = 0x0000
CONFIG_COMP_LAT_NON_LATCHING = 0x0000
CONFIG_COMP_QUE_DISABLE = 0x0003


def create_config(channel: int, gain: int = 4096, data_rate: int = 128) -> int:
    """Creates the configuration value for the ADS1115."""
    if not 0 <= channel <= 3:
        raise ValueError("Invalid channel. Must be between 0 and 3.")

    if not 2048 <= gain <= 65536:
        raise ValueError("Invalid gain. Must be between 2048 and 65536.")

    if data_rate not in (128, 250, 490, 980):
        raise ValueError("Invalid data rate.")

    config = (
        CONFIG_OS_START
        + CONFIG_MUX_AIN0P_GNDN
        + (channel << 12)
        + CONFIG_FSR_4V096
        + CONFIG_MODE_SINGLE_SHOT
        + (data_rate << 10)
        + CONFIG_COMP_MODE_TRADITIONAL
        + CONFIG_COMP_POL_ACTIVE_LOW
        + CONFIG_COMP_LAT_NON_LATCHING
        + CONFIG_COMP_QUE_DISABLE
    )
    return config


def swap_endian(word: int) -> int:
    """Swaps the endianness of a 16-bit word."""
    return ((word & 0xff00) >> 8) | ((word & 0x00ff) << 8)


def read_adc_raw(bus: smbus.SMBus, address: int, channel: int, gain: int = 4096, data_rate: int = 128) -> int:
    """Reads the raw ADC value from the specified channel."""
    config = create_config(channel, gain, data_rate)

    try:
        bus.write_word_data(address, ADS1115_CONFIG_REGISTER, swap_endian(config))
    except OSError as e:
        raise IOError(f"Error writing to ADS1115: {e}")

    start_time = time.monotonic()
    while True:
        try:
            status = swap_endian(bus.read_word_data(address, ADS1115_CONFIG_REGISTER))
        except OSError as e:
            raise IOError(f"Error reading from ADS1115: {e}")

        if (status & CONFIG_OS_START) != CONFIG_OS_START:
            break

        if time.monotonic() - start_time > 0.1:  # Timeout
            raise TimeoutError("Timeout waiting for conversion.")

        time.sleep(0.001)  # Small delay to reduce CPU usage

    try:
        result = swap_endian(bus.read_word_data(address, ADS1115_CONVERSION_REGISTER))
        return result
    except OSError as e:
        raise IOError(f"Error reading conversion result: {e}")


def convert_to_voltage(raw_value: int, gain: int = 4096) -> float:
    """Converts the raw ADC value to voltage."""
    return float(raw_value) * (gain / 32767.0) / 2.0  # Adjust for 16-bit resolution



def read_channel(bus: smbus.SMBus, address: int, channel: int, gain: int = 4096, data_rate: int = 128) -> float:
    """Reads the voltage from the specified channel."""
    try:
        raw_value = read_adc_raw(bus, address, channel, gain, data_rate)
        return convert_to_voltage(raw_value, gain)
    except (IOError, TimeoutError) as e:
        raise RuntimeError(f"Error reading channel {channel}: {e}")


def read_all_channels(bus: smbus.SMBus, address: int, gain: int = 4096, data_rate: int = 128) -> List[float]:
    """Reads the voltage from all channels."""
    return [read_channel(bus, address, i, gain, data_rate) for i in range(4)]



def main():
    """Main function to demonstrate ADS1115 usage."""
    i2c_bus = 1  # I2C bus number (usually 1 on Raspberry Pi)
    ads1115_address = ADS1115_I2C_ADDR  # I2C address of the ADS1115

    try:
        bus = smbus.SMBus(i2c_bus)
    except OSError as e:
        print(f"Error: Could not initialize I2C bus {i2c_bus}. Check I2C is enabled and the ADS1115 is connected. {e}")
        return


    try:
        while True:
            try:
                voltages = read_all_channels(bus, ads1115_address)
                print("Channel Voltages:", voltages)
                time.sleep(0.5)
            except RuntimeError as e:
                print(f"Error: {e}")
                break  # Exit the loop if an error occurs

    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        pass # No specific cleanup needed for smbus



if __name__ == "__main__":
    main()

