import spidev
import time
import signal
import sys

# Define SPI parameters
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 50000
SPI_MODE = 0b00
SPI_BITS_PER_WORD = 8

# MCP3002 channel
MCP3002_CHANNEL = 0

# Calibration factor (adjust based on your load cell)
CALIBRATION_FACTOR = 5.0 / 1023.0

# Global variable for SPI device
spi = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    cleanup()
    sys.exit(0)

def cleanup():
    """Closes the SPI connection."""
    global spi
    if spi:
        try:
            spi.close()
            print("SPI connection closed.")
        except Exception as e:
            print(f"Error closing SPI: {e}")

def send_spi_command(spi_device, command):
    """Sends a command to the MCP3002 over SPI."""
    try:
        response = spi_device.xfer2([0x01, (0x80 + MCP3002_CHANNEL) << 4, 0x00])
        return response
    except OSError as e:
        print(f"SPI communication error: {e}")
        return None
    except IOError as e:
        print(f"SPI I/O error: {e}")
        return None

def extract_10bit(response):
    """Extracts the 10-bit ADC value from the SPI response."""
    if response is None:
        return None
    try:
        adc_value = ((response[1] & 0x03) << 8) | response[2]
        return adc_value
    except IndexError:
        print("Incomplete SPI response.")
        return None

def convert_to_weight(raw_data):
    """Converts the raw ADC value to a weight in kilograms."""
    if raw_data is None:
        return None
    try:
        weight = raw_data * CALIBRATION_FACTOR
        return weight
    except TypeError:
        print("Invalid raw data type.")
        return None

class LoadCellReader:
    """A class to read data from the load cell via MCP3002 ADC."""

    def __init__(self, spi_bus, spi_device, spi_max_speed_hz, spi_mode, spi_bits_per_word):
        """Initializes the LoadCellReader."""
        global spi
        try:
            spi = spidev.SpiDev()
            spi.open(spi_bus, spi_device)
            spi.max_speed_hz = spi_max_speed_hz
            spi.mode = spi_mode
            spi.bits_per_word = spi_bits_per_word
            print("SPI initialized successfully.")
        except Exception as e:
            print(f"Error initializing SPI: {e}")
            sys.exit(1)

    def read_raw_data(self):
        """Reads raw data from the MCP3002 ADC."""
        response = send_spi_command(spi, [0x01, (0x80 + MCP3002_CHANNEL) << 4, 0x00])
        return extract_10bit(response)

    def convert_to_weight(self, raw_data):
        """Converts the raw ADC value to a weight in kilograms."""
        return convert_to_weight(raw_data)

    def close(self):
        """Closes the SPI connection."""
        cleanup()

def main():
    """Main function to read and display weight data."""
    global spi
    load_cell_reader = LoadCellReader(SPI_BUS, SPI_DEVICE, SPI_MAX_SPEED_HZ, SPI_MODE, SPI_BITS_PER_WORD)

    try:
        while True:
            raw_data = load_cell_reader.read_raw_data()
            if raw_data is not None:
                weight = load_cell_reader.convert_to_weight(raw_data)
                if weight is not None:
                    print(f'Weight: {weight:.2f} kg')
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        load_cell_reader.close()
        print("Program finished.")

if __name__ == "__main__":
    # Register the signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)  # Handle systemd kill signals
    main()

