import board
import busio
import adafruit_bmp280
import adafruit_bme280
import adafruit_ms8607
import sqlite3
import time
import logging
import signal
import sys
import configparser

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
running = True
db_conn = None
db_cursor = None

def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) to gracefully exit the program."""
    global running, db_conn
    print("Exiting gracefully...")
    running = False
    if db_conn:
        db_conn.close()
    sys.exit(0)

def read_config(config_file='config.txt'):
    """Reads configuration from the config file."""
    config = configparser.ConfigParser()
    try:
        config.read(config_file)
        sensors = []
        for i in range(1, 4):
            sensor_type = config.get(f'Sensor{i}', 'Type')
            sensor_address = config.get(f'Sensor{i}', 'Address', fallback=None)
            sensor_id = config.get(f'Sensor{i}', 'ID', fallback=None)
            sensors.append((sensor_type, sensor_address, sensor_id))
        sampling_interval = config.getint('DEFAULT', 'Sampling_Interval_Seconds', fallback=60)
        return sensors, sampling_interval
    except FileNotFoundError:
        logging.error(f"Config file not found: {config_file}")
        return [], 60  # Default sampling interval
    except configparser.Error as e:
        logging.error(f"Error parsing config file: {e}")
        return [], 60
    except Exception as e:
        logging.error(f"Unexpected error reading config: {e}")
        return [], 60

def initialize_sensors(sensors):
    """Initializes the sensors based on the configuration."""
    i2c = busio.I2C(board.SCL, board.SDA)
    sensor_objects = []
    for sensor_type, sensor_address, sensor_id in sensors:
        try:
            if sensor_type == 'BMP280':
                if sensor_address:
                    sensor = adafruit_bmp280.BMP280_I2C(i2c, address=int(sensor_address, 0))
                else:
                    sensor = adafruit_bmp280.BMP280_I2C(i2c)
                sensor_objects.append((sensor, sensor_type, sensor_id))
            elif sensor_type == 'BME280':
                if sensor_address:
                    sensor = adafruit_bme280.BME280_I2C(i2c, address=int(sensor_address, 0))
                else:
                    sensor = adafruit_bme280.BME280_I2C(i2c)
                sensor_objects.append((sensor, sensor_type, sensor_id))
            elif sensor_type == 'MS8607':
                if sensor_address:
                    sensor = adafruit_ms8607.MS8607(i2c, address=int(sensor_address, 0))
                else:
                    sensor = adafruit_ms8607.MS8607(i2c)
                sensor_objects.append((sensor, sensor_type, sensor_id))
            else:
                logging.warning(f"Unknown sensor type: {sensor_type}")
        except Exception as e:
            logging.error(f"Failed to initialize sensor {sensor_type}: {e}")
    return sensor_objects

def validate_sensor(sensor_type, sensor):
    """Validates the sensor type and performs basic checks."""
    if sensor_type == 'BMP280':
        try:
            chip_id = sensor.get_chip_id()
            if chip_id != 0x58:
                logging.error(f"BMP280 not found at address {sensor.address}")
                return False
        except Exception as e:
            logging.error(f"Error validating BMP280: {e}")
            return False
    elif sensor_type == 'BME280':
        try:
            chip_id = sensor.get_chip_id()
            if chip_id != 0x60:
                logging.error(f"BME280 not found at address {sensor.address}")
                return False
        except Exception as e:
            logging.error(f"Error validating BME280: {e}")
            return False
    elif sensor_type == 'MS8607':
        try:
            sensor.get_temperature() # Test if sensor is present
        except Exception as e:
            logging.error(f"MS8607 not found at address {sensor.address}")
            return False
    return True

def read_sensor_data(sensor, sensor_type):
    """Reads pressure, temperature, and humidity from the sensor."""
    try:
        if sensor_type == 'BMP280':
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = None
        elif sensor_type == 'BME280':
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.humidity
        elif sensor_type == 'MS8607':
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.humidity
        else:
            pressure = None
            temperature = None
            humidity = None
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None, None

def validate_data(pressure, temperature, humidity):
    """Validates the sensor data."""
    if pressure is not None and (pressure < 70000 or pressure > 110000):
        logging.warning(f"Invalid pressure reading: {pressure}")
        return False
    if temperature is not None and (temperature < -20 or temperature > 50):
        logging.warning(f"Invalid temperature reading: {temperature}")
        return False
    if humidity is not None and (humidity < 0 or humidity > 100):
        logging.warning(f"Invalid humidity reading: {humidity}")
        return False
    return True

def store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    """Stores the sensor data in the SQLite database."""
    try:
        db_cursor.execute("INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent) VALUES (?, ?, ?, ?, ?, ?)",
                          (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    """Main function to run the sensor data logging program."""
    global db_conn, db_cursor
    sensors, sampling_interval = read_config()
    sensor_objects = initialize_sensors(sensors)

    # Filter out invalid sensors
    valid_sensors = []
    for sensor_object, sensor_type, sensor_id in sensor_objects:
        if validate_sensor(sensor_type, sensor_object):
            valid_sensors.append((sensor_object, sensor_type, sensor_id))

    if not valid_sensors:
        logging.error("No valid sensors found. Exiting.")
        return

    # Initialize database
    try:
        db_conn = sqlite3.connect('wildlife_data.db')
        db_cursor = db_conn.cursor()
        db_cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        db_conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database connection error: {e}")
        return

    print("Starting sensor data logging...")
    while running:
        for sensor_object, sensor_type, sensor_id in valid_sensors:
            timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
            pressure, temperature, humidity = read_sensor_data(sensor_object, sensor_type)

            if pressure is not None and temperature is not None:
                if validate_data(pressure, temperature, humidity):
                    store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity)
                    print(f"{timestamp} - {sensor_type} ({sensor_id}): Pressure={pressure:.2f} Pa, Temperature={temperature:.2f} °C, Humidity={humidity:.2f} %")
                else:
                    logging.warning(f"Invalid data from {sensor_type} ({sensor_id}) at {timestamp}")
            else:
                logging.warning(f"Failed to read data from {sensor_type} ({sensor_id}) at {timestamp}")

        time.sleep(sampling_interval)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    main()

