import cv2
import numpy as np
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def apply_gaussian_blur(frame, kernel_size=(3, 3)):
    """Applies Gaussian blur to a frame."""
    try:
        return cv2.GaussianBlur(frame, kernel_size, 0)
    except Exception as e:
        logging.error(f"Error applying Gaussian blur: {e}")
        return frame

def apply_lighting_compensation(frame):
    """Applies lighting compensation using CLAHE."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        return clahe.apply(gray)
    except Exception as e:
        logging.error(f"Error applying lighting compensation: {e}")
        return frame

def calculate_mse(frame1, frame2):
    """Calculates the Mean Squared Error between two frames."""
    try:
        err = np.sum((frame1.astype("float") - frame2.astype("float")) ** 2)
        err /= float(frame1.shape[0] * frame1.shape[1])
        return err
    except Exception as e:
        logging.error(f"Error calculating MSE: {e}")
        return 0.0

def detect_edges(frame, threshold1, threshold2):
    """Detects edges using Canny edge detection."""
    try:
        return cv2.Canny(frame, threshold1, threshold2)
    except Exception as e:
        logging.error(f"Error detecting edges: {e}")
        return frame

def main():
    """Main function to capture video, process frames, and detect motion."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")

        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 320)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 240)

        motion_threshold = 100.0
        previous_frame = None

        while True:
            ret, frame = cap.read()
            if not ret:
                break

            processed_frame = apply_gaussian_blur(frame)
            compensated_frame = apply_lighting_compensation(processed_frame)

            gray_frame = cv2.cvtColor(processed_frame, cv2.COLOR_BGR2GRAY)
            edges = detect_edges(gray_frame, 100, 200)

            if previous_frame is not None:
                mse = calculate_mse(gray_frame, previous_frame)
                if mse > motion_threshold:
                    logging.info('Motion Detected using MSE!')

            cv2.imshow('Original', frame)
            cv2.imshow('Compensated', compensated_frame)
            cv2.imshow('Grayscale', gray_frame)
            cv2.imshow('Edges', edges)

            previous_frame = gray_frame.copy()  # Important: Create a copy

            if cv2.waitKey(1) & 0xFF == 27:
                break

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if 'cap' in locals() and cap.isOpened():
            cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

