import gpiozero
import time
import logging
import json
import signal
import sys
import os

# Constants and configuration
CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

# Global variables
config = DEFAULT_CONFIG
sensor_readings = {}
last_alert_time = {}
running = True

# Custom exception classes
class SensorTimeoutError(Exception):
    pass

class InvalidConfigError(Exception):
    pass

# Configuration management functions
def load_config(filename):
    global config
    try:
        with open(filename, "r") as f:
            config = json.load(f)
        validate_config(config)
    except FileNotFoundError:
        logging.warning(f"Config file not found. Using default configuration.")
        config = DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in config file. Using default configuration.")
        config = DEFAULT_CONFIG
    except InvalidConfigError as e:
        logging.error(f"Invalid configuration: {e}. Using default configuration.")
        config = DEFAULT_CONFIG

def validate_config(config):
    if not isinstance(config, dict):
        raise InvalidConfigError("Config must be a dictionary.")
    if "sensors" not in config or not isinstance(config["sensors"], list):
        raise InvalidConfigError("Sensors must be a list.")
    for sensor in config["sensors"]:
        if not isinstance(sensor, dict):
            raise InvalidConfigError("Each sensor must be a dictionary.")
        if "trigger_pin" not in sensor or not isinstance(sensor["trigger_pin"], int):
            raise InvalidConfigError("Trigger pin must be an integer.")
        if "echo_pin" not in sensor or not isinstance(sensor["echo_pin"], int):
            raise InvalidConfigError("Echo pin must be an integer.")
        if "offset" not in sensor or not isinstance(sensor["offset"], (int, float)):
            raise InvalidConfigError("Offset must be a number.")
        if "max_distance" not in sensor or not isinstance(sensor["max_distance"], (int, float)):
            raise InvalidConfigError("Max distance must be a number.")
    if "alert_threshold_low" not in config or not isinstance(config["alert_threshold_low"], (int, float)):
        raise InvalidConfigError("Alert threshold low must be a number.")
    if "alert_threshold_high" not in config or not isinstance(config["alert_threshold_high"], (int, float)):
        raise InvalidConfigError("Alert threshold high must be a number.")
    if "alert_repeat_delay" not in config or not isinstance(config["alert_repeat_delay"], int):
        raise InvalidConfigError("Alert repeat delay must be an integer.")
    if "log_file" not in config or not isinstance(config["log_file"], str):
        raise InvalidConfigError("Log file must be a string.")

# Modular subsystem functions
def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    """Measures the distance using an HC-SR04 ultrasonic sensor."""
    try:
        trigger = gpiozero.OutputDevice(trigger_pin)
        echo = gpiozero.InputDevice(echo_pin)

        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        pulse_start = time.time()
        pulse_end = time.time()

        # Wait for the echo pin to go high with a timeout
        timeout_start = time.time()
        while echo.value == 0:
            pulse_start = time.time()
            if time.time() - timeout_start > 0.05:  # 50ms timeout
                raise SensorTimeoutError("Echo signal timeout waiting for rising edge")
            time.sleep(0.00001)

        # Wait for the echo pin to go low with a timeout
        timeout_start = time.time()
        while echo.value == 1:
            pulse_end = time.time()
            if time.time() - timeout_start > 0.05:  # 50ms timeout
                raise SensorTimeoutError("Echo signal timeout waiting for falling edge")
            time.sleep(0.00001)

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2  # Speed of sound in cm/s
        distance += offset
        distance = min(distance, max_distance)  # Clamp to max distance

        return distance

    except SensorTimeoutError as e:
        logging.warning(f"Sensor timeout: {e}")
        return None
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None
    finally:
        trigger.close()
        echo.close()

def calculate_water_level(distance, max_distance):
    """Calculates the water level based on the measured distance."""
    if distance is None:
        return None
    water_level = max_distance - distance
    return water_level

def check_alerts(water_level, sensor_id):
    """Checks if the water level is within the alert thresholds."""
    if water_level is None:
        return

    alert_threshold_low = config["alert_threshold_low"]
    alert_threshold_high = config["alert_threshold_high"]
    alert_repeat_delay = config["alert_repeat_delay"]

    if water_level < alert_threshold_low:
        if sensor_id not in last_alert_time or time.time() - last_alert_time[sensor_id] > alert_repeat_delay:
            logging.warning(f"Low water level detected for sensor {sensor_id}: {water_level:.2f} cm")
            last_alert_time[sensor_id] = time.time()
    elif water_level > alert_threshold_high:
        if sensor_id not in last_alert_time or time.time() - last_alert_time[sensor_id] > alert_repeat_delay:
            logging.warning(f"High water level detected for sensor {sensor_id}: {water_level:.2f} cm")
            last_alert_time[sensor_id] = time.time()

# Resource management functions
def initialize_gpio():
    """Initializes the GPIO pins for the ultrasonic sensors."""
    try:
        # No explicit GPIO initialization needed with gpiozero, as it handles pin setup
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        return False
    return True

def cleanup_gpio():
    """Cleans up the GPIO pins."""
    try:
        # gpiozero automatically cleans up resources when objects are garbage collected
        logging.info("GPIO cleaned up successfully.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

# Signal handlers
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global running
    logging.info("Received signal, shutting down...")
    running = False

# Logging configuration and utilities
def setup_logging(log_file):
    """Sets up the logging configuration."""
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    # Add a rotating file handler to limit log file size
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    handler.setFormatter(logging.Formatter("%(asctime)s - %(levelname)s - %(message)s"))
    logging.getLogger().addHandler(handler)

# Main program orchestration
def main():
    """Main function to run the water level monitoring system."""
    global running
    setup_logging(config["log_file"])
    load_config(CONFIG_FILE)

    if not initialize_gpio():
        logging.error("Failed to initialize GPIO. Exiting.")
        sys.exit(1)

    sensors = config["sensors"]
    sensor_ids = [f"sensor{i+1}" for i in range(len(sensors))]

    # Initialize sensor readings and last alert times
    for sensor_id in sensor_ids:
        sensor_readings[sensor_id] = []
        last_alert_time[sensor_id] = 0

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    consecutive_errors = {sensor_id: 0 for sensor_id in sensor_ids}

    try:
        while running:
            all_water_levels = []
            for i, sensor in enumerate(sensors):
                sensor_id = sensor_ids[i]
                trigger_pin = sensor["trigger_pin"]
                echo_pin = sensor["echo_pin"]
                offset = sensor["offset"]
                max_distance = sensor["max_distance"]

                try:
                    distance = measure_distance(trigger_pin, echo_pin, offset, max_distance)
                    if distance is not None:
                        water_level = calculate_water_level(distance, max_distance)
                        sensor_readings[sensor_id].append(water_level)
                        consecutive_errors[sensor_id] = 0  # Reset error count
                        all_water_levels.append(water_level)
                    else:
                        consecutive_errors[sensor_id] += 1
                        if consecutive_errors[sensor_id] >= 5:
                            logging.error(f"Sensor {sensor_id} consistently failing. Excluding from readings.")
                            sensor_readings[sensor_id].clear() # Clear readings to avoid stale data
                except Exception as e:
                    logging.error(f"Error reading sensor {sensor_id}: {e}")
                    consecutive_errors[sensor_id] += 1
                    if consecutive_errors[sensor_id] >= 5:
                        logging.error(f"Sensor {sensor_id} consistently failing. Excluding from readings.")
                        sensor_readings[sensor_id].clear() # Clear readings to avoid stale data

            # Calculate average water level from valid readings
            valid_readings = [reading for readings in sensor_readings.values() if readings]
            if valid_readings:
                average_water_level = sum(sum(readings) for readings in valid_readings) / sum(len(readings) for readings in valid_readings)
                check_alerts(average_water_level, "average")
            else:
                logging.warning("No valid sensor readings. Skipping alert check.")

            # Log sensor readings
            for sensor_id, readings in sensor_readings.items():
                if readings:
                    logging.info(f"Sensor {sensor_id}: {readings[-1]:.2f} cm")
                else:
                    logging.info(f"Sensor {sensor_id}: No readings available.")

            time.sleep(5)  # Poll every 5 seconds

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()
        logging.info("Exiting program.")

# Entry point
if __name__ == "__main__":
    main()

