def turn_lights_on():
    if gpio_available:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        print("Lights turned on (simulated)")
    else:
        print("Lights turned on (simulated - GPIO unavailable)")

def turn_lights_off():
    if gpio_available:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        print("Lights turned off (simulated)")
    else:
        print("Lights turned off (simulated - GPIO unavailable)")

def read_temperature():
    if dht_available:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                print(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                print("Failed to read temperature from DHT sensor.")
                return None
        except Exception as e:
            print(f"Error reading temperature: {e}")
            return None
    else:
        # Simulate temperature reading
        temperature = 25 + (time.time() % 10) - 5  # Simulate temperature between 20 and 30
        print(f"Simulated Temperature: {temperature:.1f}°C")
        return temperature

def capture_image():
    if camera_available:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        filename = f"greenhouse_{timestamp}.jpg"
        try:
            picam2.capture_file(filename)
            print(f"Image captured: {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
    else:
        print("Camera unavailable, cannot capture image.")

# Voice recognition function
