    r = sr.Recognizer()
    with sr.Microphone() as source:
        print("Say something!")
        r.adjust_for_ambient_noise(source)  # Adjust for background noise
        try:
            audio = r.listen(source, timeout=5)  # Listen for 5 seconds
        except sr.WaitTimeoutError:
            print("No speech detected.")
            return

    try:
        text = r.recognize_google(audio)
        print(f"You said: {text}")
        process_command(text.lower())
    except sr.UnknownValueError:
        print("Could not understand audio")
    except sr.RequestError as e:
        print(f"Could not request results from Google Speech Recognition service; {e}")

# Command processing function
def process_command(command):
    if WAKE_WORD in command:
        command = command.replace(WAKE_WORD, "").strip()
        if "turn on the lights" in command:
            turn_lights_on()
        elif "turn off the lights" in command:
            turn_lights_off()
        elif "what is the temperature" in command:
            read_temperature()
        elif "take a picture" in command:
            capture_image()
        else:
            print("Unknown command.")
    else:
        print("Wake word not detected.")

# Main loop
if __name__ == "__main__":
    print("Greenhouse Control System started. Listening for commands...")
    try:
        while True:
            listen_for_commands()
            time.sleep(0.1)  # Small delay to reduce CPU usage
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        if gpio_available:
            GPIO.cleanup()
        if camera_available:
            picam2.close()
        print("Program finished.")

