import time
import board
import busio
import RPi.GPIO as GPIO
from adafruit_character_lcd.character_lcd_i2c import Character_LCD_I2C
from adafruit_dht import DHT22

# Configuration
I2C_ADDR = 0x27
LCD_COLUMNS = 16
LCD_ROWS = 2
DHT_PIN = board.D4
READ_INTERVAL = 2  # seconds

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_lcd(i2c_bus):
    """Initialize the LCD display."""
    try:
        return Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, address=I2C_ADDR)
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        return None

def initialize_dht_sensor(dht_pin):
    """Initialize the DHT22 sensor."""
    try:
        return DHT22(dht_pin)
    except Exception as e:
        print(f"Error initializing DHT sensor: {e}")
        return None

def read_sensor_data(dht_sensor):
    """Read temperature and humidity from the DHT sensor."""
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT sensor error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT sensor: {e}")
        return None, None

def display_data(lcd_display, temperature, humidity):
    """Display temperature and humidity on the LCD."""
    if temperature is not None and humidity is not None:
        lcd_display.message = f"Temp: {temperature:.1f}C\nHumidity: {humidity:.0f}%"
    else:
        lcd_display.message = "Sensor Error\nCheck Connection"

def main():
    """Main function to read sensor data and display it on the LCD."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    lcd_display = initialize_lcd(i2c_bus)
    if lcd_display is None:
        return

    dht_sensor = initialize_dht_sensor(DHT_PIN)
    if dht_sensor is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)
            display_data(lcd_display, temperature, humidity)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        lcd_display.clear()
        if i2c_bus:
            i2c_bus.deinit()
        GPIO.cleanup()  # Clean up GPIO settings

if __name__ == "__main__":
    main()

