import RPi.GPIO as GPIO
import time
import datetime
import sqlite3
import json
import logging
import random

# Configure logging
logging.basicConfig(filename='air_quality_monitor.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Default configuration values
DEFAULT_CONFIG = {
    "gpio_button_pin": None,
    "update_interval_seconds": 600
}

def load_config(config_file="config.json"):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        # Validate config values
        if not isinstance(config.get("gpio_button_pin"), (int, type(None))):
            logging.error("Invalid gpio_button_pin in config.json. Using default.")
            config["gpio_button_pin"] = DEFAULT_CONFIG["gpio_button_pin"]
        if not isinstance(config.get("update_interval_seconds"), (int, type(None))):
            logging.error("Invalid update_interval_seconds in config.json. Using default.")
            config["update_interval_seconds"] = DEFAULT_CONFIG["update_interval_seconds"]
        if config.get("update_interval_seconds", DEFAULT_CONFIG["update_interval_seconds"]) < 300:
            logging.warning("update_interval_seconds is below minimum (300 seconds). Clamping to 300.")
            config["update_interval_seconds"] = 300
        return config
    except FileNotFoundError:
        logging.warning("config.json not found. Using default configuration.")
        return DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error("Error decoding config.json. Using default configuration.")
        return DEFAULT_CONFIG
    except Exception as e:
        logging.error(f"Error loading config: {e}. Using default configuration.")
        return DEFAULT_CONFIG

def create_database():
    """Creates the SQLite database and table if they don't exist."""
    try:
        conn = sqlite3.connect('air_quality.db')
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS readings (
                timestamp TEXT,
                aqi INTEGER,
                pm25 REAL
            )
        ''')
        conn.commit()
        conn.close()
        logging.info("Database created/connected successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def simulate_sensor_reading():
    """Simulates reading air quality data."""
    if random.random() < 0.2:  # Simulate a 20% chance of sensor error
        return None
    aqi = random.randint(0, 200)
    pm25 = round(random.uniform(5, 35), 2)
    return aqi, pm25

def update_display(aqi, pm25):
    """Simulates updating the e-paper display."""
    timestamp = datetime.datetime.now().isoformat()
    alert = ""
    if aqi >= 150:
        alert = "RED Unhealthy"
    elif aqi >= 100:
        alert = "ORANGE Unhealthy for Sensitive Groups"
    elif aqi >= 50:
        alert = "YELLOW Moderate"
    else:
        alert = "GREEN Good"

    display_text = f"""
    Timestamp: {timestamp}
    AQI: {aqi}
    PM2.5: {pm25:.2f} µg/m³
    Alert: {alert}
    """
    print(display_text)  # Simulate printing to e-paper display

def button_callback(channel):
    """Callback function for the button press."""
    logging.info("Button pressed!")
    aqi, pm25 = simulate_sensor_reading()
    if aqi is not None and pm25 is not None:
        print(f"Button pressed! AQI: {aqi}, PM2.5: {pm25:.2f} µg/m³")
        # Simulate a more detailed explanation of AQI
        if aqi < 50:
            print("AQI is low, indicating good air quality. No significant health concerns.")
        elif 50 <= aqi < 100:
            print("AQI is moderate, indicating some air pollution. Sensitive individuals may experience effects.")
        elif 100 <= aqi < 150:
            print("AQI is high, indicating unhealthy air quality for sensitive groups. Limit outdoor exertion.")
        else:
            print("AQI is very high, indicating unhealthy air quality for everyone. Limit outdoor activity.")
    else:
        print("Sensor reading failed.")

def main():
    """Main function to run the air quality monitoring system."""
    config = load_config()
    gpio_button_pin = config.get("gpio_button_pin")
    update_interval_seconds = config.get("update_interval_seconds")

    create_database()

    # Initialize GPIO if button is configured
    if gpio_button_pin is not None and isinstance(gpio_button_pin, int):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(gpio_button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.add_event_detect(gpio_button_pin, GPIO.FALLING, callback=button_callback, bouncetime=200)
            logging.info(f"Button initialized on GPIO {gpio_button_pin}")
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}. Disabling button functionality.")
            gpio_button_pin = None  # Disable button functionality
    else:
        logging.info("Button disabled in configuration.")

    try:
        while True:
            aqi, pm25 = simulate_sensor_reading()
            if aqi is not None and pm25 is not None:
                timestamp = datetime.datetime.now().isoformat()
                try:
                    conn = sqlite3.connect('air_quality.db')
                    cursor = conn.cursor()
                    cursor.execute("INSERT INTO readings (timestamp, aqi, pm25) VALUES (?, ?, ?)",
                                   (timestamp, aqi, pm25))
                    conn.commit()
                    conn.close()
                    logging.info(f"Data logged: Timestamp={timestamp}, AQI={aqi}, PM2.5={pm25}")
                    update_display(aqi, pm25)  # Simulate e-paper display update
                except sqlite3.Error as e:
                    logging.error(f"Database error: {e}")
            else:
                logging.warning("Sensor reading failed. Skipping data logging and display update.")

            time.sleep(update_interval_seconds)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if gpio_button_pin is not None:
            GPIO.cleanup()  # Clean up GPIO on exit
        logging.info("Program exiting.")

if __name__ == "__main__":
    main()

