import serial
import time

# Configuration for the RS485 serial port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
DATA_BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1  # seconds

def initialize_serial(port, baudrate, bytesize, parity, stopbits, timeout):
    """Initializes and returns a serial port object."""
    try:
        ser = serial.Serial(port, baudrate, bytesize, parity, stopbits, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature_data(serial_port):
    """Reads a line of data from the serial port and returns it."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def parse_temperature_data(data):
    """Parses the data string and returns the temperature if found, otherwise None."""
    if data:
        try:
            temperature = float(data.split()[0])  # Assumes temperature is the first value
            return temperature
        except ValueError:
            print("Invalid data format received.")
            return None
    return None

def display_temperature(temperature):
    """Prints the temperature to the console."""
    if temperature is not None:
        print(f'Temperature: {temperature:.1f} C')

def main():
    """Main function to read and display temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, DATA_BITS, PARITY, STOP_BITS, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            data = read_temperature_data(serial_connection)
            temperature = parse_temperature_data(data)
            display_temperature(temperature)
            time.sleep(0.5)  # Reduced delay for faster updates

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

