def main():
    """Main function to continuously monitor and display CPU temperature."""
    try:
        while True:
            temperature = read_cpu_temperature()  # Read the temperature
            display_temperature(temperature)  # Display the temperature
            time.sleep(5)  # Wait for 5 seconds
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An error occurred in the main loop: {e}")

