import RPi.GPIO as GPIO
import time
import random
import logging

# Configure logging to a file for greenhouse vent control
logging.basicConfig(filename='greenhouse_vent.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pin assignments for the two servo motors
SERVO_PIN_1 = 17
SERVO_PIN_2 = 18

# Servo frequency in Hz
SERVO_FREQUENCY = 50

# Duty cycle range for SG90 servo (0-180 degrees)
DUTY_CYCLE_MIN = 2.5
DUTY_CYCLE_MAX = 12.5

# Temperature thresholds for vent control
TEMPERATURE_THRESHOLDS = {
    0: 20,  # Vent closed (0 degrees)
    45: 25, # Vent partially open (45 degrees)
    90: 30, # Vent half open (90 degrees)
    135: 35 # Vent fully open (135 degrees)
}

# Failure rate for servo 1 (simulated)
SERVO1_FAILURE_RATE = 0.1

# Number of consecutive failures before switching to servo 2
MAX_FAILURES = 3

# Global variables
servo1_pwm = None
servo2_pwm = None
use_servo1 = True
failure_count = 0

def setup_gpio():
    """Sets up the GPIO pins for the servo motors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        global servo1_pwm, servo2_pwm
        servo1_pwm = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
        servo2_pwm = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
        servo1_pwm.start(0) # Start with 0% duty cycle (servo off)
        servo2_pwm.start(0) # Start with 0% duty cycle (servo off)
        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return False
    return True

def set_servo_angle(servo_pwm, angle):
    """Sets the angle of the servo motor using PWM duty cycle."""
    try:
        duty_cycle = DUTY_CYCLE_MIN + (float(angle) / 180) * (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN)
        servo_pwm.ChangeDutyCycle(duty_cycle)
        logging.info(f"Servo angle set to {angle} degrees.")
    except Exception as e:
        logging.error(f"Failed to set servo angle: {e}")
        return False
    return True

def move_servo_smoothly(servo_pwm, start_angle, end_angle, step_size=5, delay=0.1):
    """Moves the servo smoothly from start_angle to end_angle."""
    try:
        current_angle = start_angle
        if end_angle > start_angle:
            while current_angle < end_angle:
                current_angle += step_size
                if current_angle > end_angle:
                    current_angle = end_angle
                set_servo_angle(servo_pwm, current_angle)
                time.sleep(delay)
        else:
            while current_angle > end_angle:
                current_angle -= step_size
                if current_angle < end_angle:
                    current_angle = end_angle
                set_servo_angle(servo_pwm, current_angle)
                time.sleep(delay)
    except Exception as e:
        logging.error(f"Failed to move servo smoothly: {e}")
        return False
    return True

def get_temperature():
    """Simulates reading the temperature from a sensor."""
    try:
        temperature = random.uniform(15, 35)
        logging.info(f"Simulated temperature: {temperature:.2f}°C")
        return temperature
    except Exception as e:
        logging.error(f"Failed to get temperature: {e}")
        return None

def control_vent(temperature):
    """Controls the vent based on the temperature."""
    global use_servo1, failure_count
    try:
        if use_servo1:
            servo = servo1_pwm
        else:
            servo = servo2_pwm

        if temperature is None:
            logging.warning("Temperature is None, skipping vent control.")
            return

        if temperature < TEMPERATURE_THRESHOLDS[0]:
            target_angle = 0
        elif temperature < TEMPERATURE_THRESHOLDS[45]:
            target_angle = 45
        elif temperature < TEMPERATURE_THRESHOLDS[90]:
            target_angle = 90
        elif temperature < TEMPERATURE_THRESHOLDS[135]:
            target_angle = 135
        else:
            target_angle = 180

        if use_servo1:
            if random.random() < SERVO1_FAILURE_RATE:
                logging.warning("Simulated servo 1 failure!")
                failure_count += 1
                if failure_count >= MAX_FAILURES:
                    logging.warning("Switching to servo 2 permanently.")
                    use_servo1 = False
                    failure_count = 0
                    return
            else:
                failure_count = 0 # Reset failure count if successful

        move_servo_smoothly(servo, 0, target_angle)

    except Exception as e:
        logging.error(f"Failed to control vent: {e}")

def cleanup_gpio():
    """Cleans up the GPIO pins."""
    try:
        if servo1_pwm:
            servo1_pwm.stop()
        if servo2_pwm:
            servo2_pwm.stop()
        GPIO.cleanup()
        logging.info("GPIO cleanup complete.")
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")

if __name__ == "__main__":
    try:
        if not setup_gpio():
            exit(1)

        logging.info("Greenhouse vent controller started.")

        while True:
            temperature = get_temperature()
            control_vent(temperature)
            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()
        logging.info("Greenhouse vent controller stopped.")

