import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for signal levels
HIGH = GPIO.HIGH
LOW = GPIO.LOW

# Constants for start and end signals
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]

# Global variable to track program state
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info("Received signal, shutting down...")
    running = False

def initialize_gpio():
    """Initializes GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=LOW)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=LOW)
        GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        raise

def cleanup_gpio():
    """Cleans up GPIO pins."""
    try:
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")


def send_bit(bit):
    """Sends a single bit."""
    try:
        GPIO.output(TIMER_OUT_PIN, HIGH)
        GPIO.output(DATA_OUT_PIN, bit)
        time.sleep(0.0005)  # Adjust delay as needed
        GPIO.output(TIMER_OUT_PIN, LOW)
        time.sleep(0.0005)  # Adjust delay as needed
        GPIO.output(TIMER_OUT_PIN, HIGH)
        time.sleep(0.0005)  # Adjust delay as needed
        GPIO.output(TIMER_OUT_PIN, LOW)
    except Exception as e:
        logging.error(f"Error sending bit: {e}")
        raise


def send_byte(byte):
    """Sends a byte by transmitting its bits."""
    try:
        for bit in [0] + [int(bit) for bit in bin(byte)[2:].zfill(7)]:
            send_bit(bit)
    except Exception as e:
        logging.error(f"Error sending byte: {e}")
        raise


def send_data(data):
    """Sends a string of data with start and end signals."""
    try:
        for bit in START_SIGNAL:
            send_bit(bit)

        for char in data:
            ascii_value = ord(char)
            send_byte(ascii_value)

        for bit in END_SIGNAL:
            send_bit(bit)

        logging.info(f"Data sent successfully: {data}")
    except Exception as e:
        logging.error(f"Data transmission failed: {e}")
        raise


def receive_bit():
    """Receives a single bit with timeout."""
    timeout = time.time() + 1  # Set a timeout of 1 second
    while time.time() < timeout:
        if GPIO.input(TIMER_IN_PIN) == HIGH:
            return HIGH if GPIO.input(DATA_IN_PIN) == HIGH else LOW
    raise TimeoutError("Timeout waiting for data")


def receive_byte():
    """Receives a byte by reading bits."""
    try:
        byte = 0
        for _ in range(7):
            bit = receive_bit()
            byte = (byte << 1) | bit
        return byte
    except TimeoutError:
        raise


def receive_data():
    """Receives data with start and end signals."""
    try:
        received_data = ""
        while True:
            bit = receive_bit()
            if [bit] == START_SIGNAL[:-1]:  # Check for start signal
                break
            elif [bit] == END_SIGNAL[:-1]:  # Check for end signal
                return received_data
            else:
                try:
                    byte = receive_byte()
                    received_data += chr(byte)
                except TimeoutError:
                    raise

        while True:  # Receive data after start signal
            bit = receive_bit()
            if [bit] == END_SIGNAL[:-1]:  # Check for end signal
                return received_data
            else:
                try:
                    byte = receive_byte()
                    received_data += chr(byte)
                except TimeoutError:
                    raise
    except TimeoutError:
        raise


def main():
    """Main function."""
    global running
    initialize_gpio()

    try:
        while running:
            try:
                data = input("Enter data to send (or 'exit' to quit): ")
                if data.lower() == "exit":
                    break
                send_data(data)
            except Exception as e:
                logging.error(f"Error during data transmission: {e}")

    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()
        logging.info("Program finished.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

