class SubscriptionHandler:
    """
    Manages subscriptions to data streams and executes callbacks.
    """

    def __init__(self, logger: logging.Logger = None):
        """
        Initializes the SubscriptionHandler.

        Args:
            logger (logging.Logger, optional): A logger instance. If None, a default logger is created.
                                                Defaults to None.
        """
        self.logger = logger if logger else logging.getLogger(__name__)
        self.subscriptions: Dict[str, List[Dict[str, Any]]] = {}  # {stream_filter: [callback_info]}
        self.channel_info: Dict[str, Dict[str, Any]] = {}  # {channel_id: {control_dict, pause_state}}
        self.subscriber_socket: zmq.Socket = None  # ZMQ socket for subscriptions
        self.subscriber_filter: str = ""  # Current subscription filter

    def handle_command(self, command: dict) -> None:
        """
        Handles commands related to subscriptions, updates, and control.

        Args:
            command (dict): A dictionary containing the command details.  Expected keys: 'action', 'stream_filter', 'callback', 'kwargs', 'id'
        """
        action = command.get('action')

        try:
            if action == 'SUBSCRIBE':
                self._subscribe(command)
            elif action == 'UPDATE_KW':
                self._update_kwargs(command)
            elif action == 'UNSUBSCRIBE_ALL':
                self._unsubscribe_all()
            elif action == 'REMOVE_SUB':
                self._remove_subscription(command)
            elif action == 'RESET':
                self._reset_channel(command)
            elif action in ('MUTE', 'UNMUTE'):
                self._mute_channel(command)
            elif action in ('PAUSE', 'RESTART'):
                self._pause_channel(command)
            elif action in ('RESET_ALL', 'MUTE_ALL', 'UNMUTE_ALL'):
                self._reset_all_channels(action)
            elif action == 'PAUSE_ALL' or action == 'RESTART_ALL':
                self._pause_all_channels(action)
            else:
                self.logger.warning(f"Unknown action: {action}")

            self._manage_subscriber_socket()

        except KeyError as e:
            self.logger.error(f"Missing key in command: {e}")
        except Exception as e:
            self.logger.exception(f"Error handling command: {command}")

    def _manage_subscriber_socket(self):
        """Manages the ZMQ subscriber socket based on active subscriptions."""
        if self.subscriber_socket is None and self.subscriptions:
            try:
                context = zmq.Context()
                self.subscriber_socket = context.socket(zmq.SUB)
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, self.subscriber_filter)
                self.logger.info(f"Subscribed to: {self.subscriber_filter}")
            except zmq.ZMQError as e:
                self.logger.error(f"ZMQ error creating subscriber socket: {e}")
                self.subscriber_socket = None

        elif self.subscriber_socket and not self.subscriptions:
            self.subscriber_socket.close()
            self.subscriber_socket = None
            self.logger.info("No active subscriptions. Subscriber socket closed.")

    def _subscribe(self, command: dict):
        """Subscribes to a data stream."""
        stream_filter = command['stream_filter']
        channel_id = command['id']

        if channel_id in self.channel_info:
            self.logger.warning(f"Channel {channel_id} already exists. Ignoring subscribe command.")
            return

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            self.subscriber_filter = stream_filter  # Set initial filter

        callback = command['callback']
        kwargs = command.get('kwargs', {})
        state = command.get('state', {})

        self.subscriptions[stream_filter].append({
            'callback': callback,
            'kwargs': kwargs,
            'state': state,
            'channel_id': channel_id
        })
        self.channel_info[channel_id] = {
            'control_dict': {'kwargs': kwargs, 'state': state},
            'pause_state': True
        }

        self._manage_subscriber_socket()

        self.logger.info(f"Subscribed to: {stream_filter}, channel_id: {channel_id}")

    def _unsubscribe_all(self):
        """Unsubscribes from all data streams."""
        for stream_filter in list(self.subscriptions.keys()):
            try:
                if self.subscriber_socket:
                    self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
                del self.subscriptions[stream_filter]
            except zmq.ZMQError as e:
                self.logger.error(f"ZMQ error unsubscribing from {stream_filter}: {e}")
        self.subscriber_filter = ""  # Reset filter
        self._manage_subscriber_socket()
        self.logger.info("Unsubscribed from all streams.")

    def _remove_subscription(self, command: dict):
        """Removes a specific subscription."""
        stream_filter = command['stream_filter']

        if stream_filter not in self.subscriptions:
            self.logger.warning(f"No subscription found for filter: {stream_filter}")
            return

        self.subscriptions[stream_filter] = []
        self._manage_subscriber_socket()
        self.logger.info(f"Removed subscription for: {stream_filter}")

    def _update_kwargs(self, command: dict):
        """Updates the keyword arguments for a specific subscription."""
        stream_filter = command['stream_filter']
        channel_id = command['id']

        if stream_filter not in self.subscriptions:
            self.logger.warning(f"No subscription found for filter: {stream_filter}")
            return

        for subscription in self.subscriptions[stream_filter]:
            if subscription['channel_id'] == channel_id:
                subscription['kwargs'] = command['kwargs']
                self.channel_info[channel_id]['control_dict']['kwargs'] = command['kwargs']
                self.logger.info(f"Updated kwargs for channel {channel_id} on filter {stream_filter}")
                return

        self.logger.warning(f"Channel {channel_id} not found on filter {stream_filter}")

    def _reset_channel(self, command: dict):
        """Resets the state for a specific channel."""
        channel_id = command['id']
        if channel_id in self.channel_info:
            self.channel_info[channel_id]['state'] = command['kwargs']
            self.logger.info(f"Reset channel {channel_id} state: {command['kwargs']}")
        else:
            self.logger.warning(f"Channel {channel_id} not found.")

    def _mute_channel(self, command: dict):
        """Mutes or unmutes a specific channel."""
        channel_id = command['id']
        action = command['action']
        if channel_id in self.channel_info:
            self.channel_info[channel_id]['pause_state'] = (action == 'MUTE')
            self.logger.info(f"Muted channel {channel_id}: {action == 'MUTE'}")
        else:
            self.logger.warning(f"Channel {channel_id} not found.")

    def _pause_channel(self, command: dict):
        """Pauses or restarts a specific channel."""
        channel_id = command['id']
        action = command['action']
        if channel_id in self.channel_info:
            self.channel_info[channel_id]['pause_state'] = (action == 'PAUSE')
            self.logger.info(f"Paused channel {channel_id}: {action == 'PAUSE'}")
        else:
            self.logger.warning(f"Channel {channel_id} not found.")

    def _reset_all_channels(self, action: str):
        """Resets all channels."""
        for channel_id in list(self.channel_info.keys()):
            self.channel_info[channel_id]['control_dict'] = {
                'kwargs': self.channel_info[channel_id]['control_dict'].get('kwargs', {}),
                'state': self.channel_info[channel_id]['control_dict'].get('state', {})
            }
            self.channel_info[channel_id]['pause_state'] = (action == 'RESET_ALL')

    def _mute_all_channels(self, action: str):
        """Mutes or unmutes all channels."""
        for channel_id in list(self.channel_info.keys()):
            self.channel_info[channel_id]['pause_state'] = (action == 'MUTE_ALL')

    def _pause_all_channels(self, action: str):
        """Pauses or restarts all channels."""
        for channel_id in list(self.channel_info.keys()):
            self.channel_info[channel_id]['pause_state'] = (action == 'PAUSE_ALL')

    def process_message(self, subscriber_socket: zmq.Socket, message: str):
        """Processes a received message and calls the appropriate callbacks."""
        try:
            stream_filter, data = message.split(" ", 1)
            stream_filter = stream_filter.decode('utf-8') # Decode the stream_filter
            data = json.loads(data)  # Parse JSON data

            if stream_filter in self.subscriptions:
                for subscription in self.subscriptions[stream_filter]:
                    if not subscription['state'].get('pause', True):
                        subscription['callback'](data, **subscription['kwargs'])
            else:
                self.logger.warning(f"No subscription found for filter: {stream_filter}")

        except (ValueError, json.JSONDecodeError) as e:
            self.logger.error(f"Error processing message: {e}, Message: {message}")
        except Exception as e:
            self.logger.exception(f"Unexpected error processing message: {e}")


class PIDHandler:
    """
    Manages PID controllers and error output.
    """

    def __init__(self, logger: logging.Logger = None):
        """
        Initializes the PIDHandler.

        Args:
            logger (logging.Logger, optional): A logger instance. If None, a default logger is created.
                                                Defaults to None.
        """
        self.logger = logger if logger else logging.getLogger(__name__)
        self.pids: Dict[str, Dict[str, Any]] = {}  # {pid_number: {Kp, Ki, Kd, instance}}
        self.error_output: Union[GPIO.PWMOutputDevice, OutputDevice] = None  # GPIO output for errors
        self.last_msg = time.time()
        self.pwm_frequency = 1000  # Default PWM frequency

    def handle_command(self, command: dict) -> None:
        """
        Handles commands related to PID controllers.

        Args:
            command (dict): A dictionary containing the command details. Expected keys: 'action', 'pid_number', 'Kp', 'Ki', 'Kd'
        """
        action = command.get('action')
        pid_number = command.get('pid_number')

        try:
            if action == 'NEW':
                self._create_pid(command)
            elif action == 'REMOVE':
                self._remove_pid(pid_number)
            elif action in ('UPDATE', 'UPDATE_KW'):
                self._update_pid(command)
            elif action in ('RESET', 'RESET_INTEGRAL'):
                self._reset_pid(command)
            elif action in ('MUTE', 'UNMUTE'):
                self._mute_pid(command)
            elif action in ('PAUSE', 'RESTART'):
                self._pause_pid(command)
            elif action in ('PAUSE_ALL', 'RESTART_ALL'):
                self._pause_all_pids(action)
            else:
                self.logger.warning(f"Unknown action: {action}")

        except KeyError as e:
            self.logger.error(f"Missing key in command: {e}")
        except Exception as e:
            self.logger.exception(f"Error handling command: {command}")

    def _create_pid(self, command: dict):
        """Creates a new PID controller."""
        pid_number = command['pid_number']
        if pid_number in self.pids:
            self.logger.warning(f"PID {pid_number} already exists. Ignoring command.")
            return

        Kp = command.get('Kp')
        Ki = command.get('Ki')
        Kd = command.get('Kd')

        # Validate PID gains
        if not all(isinstance(g, (int, float)) for g in [Kp, Ki, Kd]):
            self.logger.error("PID gains must be numbers.")
            return

        self.pids[pid_number] = {
            'Kp': Kp,
            'Ki': Ki,
            'Kd': Kd,
            'instance': self._initialize_pid_instance(pid_number, Kp, Ki, Kd)
        }
        self.logger.info(f"Created PID {pid_number} with Kp={Kp}, Ki={Ki}, Kd={Kd}")

    def _initialize_pid_instance(self, pid_number: str, Kp: float, Ki: float, Kd: float) -> Any:
        """
        Initializes a PID controller instance using an external library.

        Returns:
            Any: The PID controller instance.
        """
        try:
            import control
            sys.modules['control'] = control  # HACK: prevent multiple imports
            pid = control.pid(Kp, Ki, Kd)
            self.logger.info(f"Initialized PID {pid_number} using 'control' library.")
            return pid
        except ImportError:
            self.logger.error("Could not import 'control' library. Using a placeholder.")
            # Placeholder PID controller (replace with a simple implementation if needed)
            class PlaceholderPID:
                def __init__(self, Kp, Ki, Kd):
                    self.Kp = Kp
                    self.Ki = Ki
                    self.Kd = Kd
                def __call__(self, *args, **kwargs):
                    return 0  # Replace with actual control logic
            return PlaceholderPID(Kp, Ki, Kd)

    def _remove_pid(self, pid_number: str):
        """Removes a PID controller."""
        if pid_number not in self.pids:
            self.logger.warning(f"PID {pid_number} does not exist.")
            return

        del self.pids[pid_number]
        self.logger.info(f"Removed PID {pid_number}")

    def _update_pid(self, command: dict):
        """Updates the PID gains for a specific PID controller."""
        pid_number = command['pid_number']
        if pid_number not in self.pids:
            self.logger.warning(f"PID {pid_number} does not exist.")
            return

        Kp = command.get('Kp')
        Ki = command.get('Ki')
        Kd = command.get('Kd')

        if Kp is not None:
            self.pids[pid_number]['Kp'] = Kp
            self.pids[pid_number]['instance'].Kp = Kp
        if Ki is not None:
            self.pids[pid_number]['Ki'] = Ki
            self.pids[pid_number]['instance'].Ki = Ki
        if Kd is not None:
            self.pids[pid_number]['Kd'] = Kd
            self.pids[pid_number]['instance'].Kd = Kd

        self.logger.info(f"Updated PID {pid_number} with Kp={Kp}, Ki={Ki}, Kd={Kd}")

    def _reset_pid(self, command: dict):
        """Resets a PID controller."""
        pid_number = command['pid_number']
        if pid_number not in self.pids:
            self.logger.warning(f"PID {pid_number} does not exist.")
            return

        action = command['action']
        if action == 'RESET':
            # Reset integral term and state (if using control library)
            self.pids[pid_number]['instance'].Ki = 0
            self.pids[pid_number]['instance'].Kd = 0
        elif action == 'RESET_INTEGRAL':
            self.pids[pid_number]['instance'].Ki = 0
        self.logger.info(f"Reset PID {pid_number} (action: {action})")

    def _mute_pid(self, command: dict):
        """Mutes or unmutes a PID controller."""
