        """Pauses or restarts a PID controller."""
        pid_number = command['pid_number']
        if pid_number not in self.pids:
            self.logger.warning(f"PID {pid_number} does not exist.")
            return

        self.pids[pid_number]['pause_state'] = (command['action'] == 'PAUSE')
        self.logger.info(f"Paused PID {pid_number}: {command['action'] == 'PAUSE'}")

    def _pause_all_pids(self, action: str):
        """Pauses or restarts all PID controllers."""
        for pid_number in list(self.pids.keys()):
            self.pids[pid_number]['pause_state'] = (action == 'PAUSE_ALL')
            self.logger.info(f"Paused PID {pid_number}: {action == 'PAUSE_ALL'}")

