        if isinstance(self.error_output, GPIO.PWMOutputDevice):
            self.error_output.value = 1.0 if state else 0.0
        else:  # OutputDevice
            self.error_output.on() if state else self.error_output.off()

        self.logger.debug(f"Error output set to: {state}")


