# Raspberry Pi 5 fingerprint authentication script for smart retail

import time
import board
import busio
import adafruit_fingerprint

# I2C configuration
I2C_ADDRESS = 0x26
SCL_PIN = board.SCL
SDA_PIN = board.SDA

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(SCL_PIN, SDA_PIN)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, addr=I2C_ADDRESS)
        return fingerprint_sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None

def authenticate_user(fingerprint_sensor):
    """Authenticates a user based on fingerprint."""
    print("Waiting for fingerprint...")
    try:
        if fingerprint_sensor.get_image() and fingerprint_sensor.image_2_tz(1) and fingerprint_sensor.finger_search():
            print("Access Granted")
            return True
        else:
            print("Access Denied")
            return False
    except Exception as e:
        print(f"Error during authentication: {e}")
        return False

def main():
    """Main function to run the fingerprint authentication."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        return

    try:
        while True:
            authenticate_user(fingerprint_sensor)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

