import time
import RPi.GPIO as GPIO
from functools import partial

class RotaryEncoder:
    """
    A robust and optimized rotary encoder interface for Raspberry Pi.

    This class provides a functional approach to handling rotary encoders,
    incorporating error handling, resource management, and performance optimizations.
    """

    def __init__(self, clk_pin, dt_pin, callback=None, initial_value=0, min_value=None, max_value=None, reverse=False, button_pin=None, button_pull_up=True, debounce_time=0.005):
        """
        Initializes the RotaryEncoder object.

        Args:
            clk_pin (int): GPIO pin number for the CLK signal.
            dt_pin (int): GPIO pin number for the DT signal.
            callback (callable, optional): Function to call when rotation is detected. 
                                            Defaults to None. The callback function should 
                                            accept a single argument: the current value.
            initial_value (int, optional): Initial value of the counter. Defaults to 0.
            min_value (int, optional): Minimum value for the counter. 
                                        If provided, the counter will be clamped to this value. Defaults to None.
            max_value (int, optional): Maximum value for the counter. 
                                        If provided, the counter will be clamped to this value. Defaults to None.
            reverse (bool, optional): If True, swaps the clockwise and counter-clockwise rotation direction. Defaults to False.
            button_pin (int, optional): GPIO pin number for the button. Defaults to None.
            button_pull_up (bool, optional):  Whether the button has a pull-up resistor. Defaults to True.
            debounce_time (float, optional): Debounce time in seconds for both rotary encoder and button. Defaults to 0.005.
        """

        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.initial_value = initial_value
        self.min_value = min_value
        self.max_value = max_value
        self.reverse = reverse
        self.button_pin = button_pin
        self.button_pull_up = button_pull_up
        self.debounce_time = debounce_time
        self.value = self.initial_value
        self.last_state = None
        self.last_button_state = None
        self._clk = None
        self._dt = None
        self._button = None

        if not all(isinstance(pin, int) for pin in [clk_pin, dt_pin]):
            raise TypeError("Pin numbers must be integers.")

        if not 0 <= debounce_time <= 0.1:
            raise ValueError("Debounce time must be between 0 and 0.1 seconds.")

        try:
            GPIO.setmode(GPIO.BCM)  # Set GPIO mode once outside the initialization block
        except Exception as e:
            raise RuntimeError(f"Error setting GPIO mode: {e}") from e


        self._setup_gpio()


        if self._button:
            self._button.when_pressed = partial(self._button_pressed, self._button)
            self._button.when_released = partial(self._button_released, self._button)


    def _setup_gpio(self):
        """Sets up the GPIO pins for the rotary encoder and button."""

        try:
            self._clk = Button(self.clk_pin, pull_up=self.button_pull_up, bounce_time=self.debounce_time)
            self._dt = Button(self.dt_pin, pull_up=self.button_pull_up, bounce_time=self.debounce_time)

            self._clk.when_pressed = self._clk_pressed
            self._clk.when_released = self._clk_released
            self._dt.when_pressed = self._dt_pressed
            self._dt.when_released = self._dt_released

            if self.button_pin is not None:
                self._button = Button(self.button_pin, pull_up=self.button_pull_up, bounce_time=self.debounce_time)
                self._button.when_pressed = partial(self._button_pressed, self._button)
                self._button.when_released = partial(self._button_released, self._button)

        except Exception as e:
            raise RuntimeError(f"Error setting up GPIO pins: {e}") from e


    def _rotate(self, increment):
        """Rotates the counter and calls the callback function."""
        if self.min_value is not None or self.max_value is not None:
            new_value = self.value + increment
            if self.min_value is not None:
                new_value = max(self.min_value, new_value)
            if self.max_value is not None:
                new_value = min(self.max_value, new_value)
            if new_value != self.value:  # Only update if the value has changed
                self.value += increment
                self._call_callback()
        else:
            self.value += increment
            self._call_callback()


    def _clk_pressed(self, *args):
        """Handles CLK pin press event."""
        if self._dt.is_pressed != self.last_state:
            if self._clk.is_pressed:
                if self.last_state is None:
                    self.last_state = self._dt.is_pressed
                return  # Ignore first press when DT is also pressed

            if self.reverse:
                self._rotate(1)
            else:
                self._rotate(-1)

    def _clk_released(self, *args):
        """Handles CLK pin release event."""
        self.last_state = self._dt.is_pressed

    def _dt_pressed(self, *args):
        """Handles DT pin press event."""
        if self._clk.is_pressed != self.last_state:
            if self._dt.is_pressed:
                if self.last_state is None:
                    self.last_state = self._clk.is_pressed
                return  # Ignore first press when CLK is also pressed

            if self.reverse:
                self._rotate(-1)
            else:
                self._rotate(1)

    def _dt_released(self, *args):
        """Handles DT pin release event."""
        self.last_state = self._clk.is_pressed

    def _button_pressed(self, button, *args):
        """Handles button press event."""
        if self.last_button_state is None:
            self.last_button_state = button.is_pressed
        if not button.is_pressed:  # Check state on release
            self._execute_action()

    def _button_released(self, button, *args):
        """Handles button release event."""
        self.last_button_state = button.is_pressed

    def _call_callback(self):
