                self.callback(self.value)
            except Exception as e:
                print(f"Error in callback function: {e}")

    def read(self):
        """Returns the current value of the counter."""
        return self.value

    def cleanup(self):
        """Cleans up the GPIO pins."""
        try:
            if self._clk:
                self._clk.close()
            if self._dt:
                self._dt.close()
            if self._button:
                self._button.close()
            GPIO.cleanup()  # Clean up all GPIO settings
        except Exception as e:
            print(f"Error during cleanup: {e}")

    def __del__(self):
        """Automatically calls cleanup when the object is deleted."""
        self.cleanup()


