# Ambient Light Control Script for Raspberry Pi
# Hobbyist Project - Adjusts LED brightness based on ambient light levels.

import time
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED
from functools import partial

# Constants
I2C_ADDRESS = 0x39
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000
MIN_LUX = 0
MAX_LUX = 1000
MIN_BRIGHTNESS = 0
MAX_BRIGHTNESS = 100

# Initialize I2C bus
def initialize_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

# Initialize TSL2561 sensor
def initialize_sensor(i2c_bus):
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

# Initialize LED
def initialize_led(gpio_pin):
    try:
        return PWMLED(gpio_pin)
    except Exception as e:
        print(f"Error initializing LED: {e}")
        return None

# Read light level from sensor
def read_light_level(sensor):
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

# Map light level to brightness percentage
def map_brightness(lux, min_lux, max_lux, min_brightness, max_brightness):
    return min(max(round((lux - min_lux) / (max_lux - min_lux) * (max_brightness - min_brightness) + min_brightness), min_brightness), max_brightness)

# Set LED brightness
def set_led_brightness(led, brightness):
    try:
        led.value = brightness / 100.0
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

# Main function
def main():
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    led = initialize_led(LED_GPIO_PIN)
    if led is None:
        return

    read_and_set_brightness = partial(read_light_level, sensor)
    set_brightness = partial(set_led_brightness, led)

    try:
        while True:
            lux = read_and_set_brightness()
            if lux is not None:
                brightness = map_brightness(lux, MIN_LUX, MAX_LUX, MIN_BRIGHTNESS, MAX_BRIGHTNESS)
                set_brightness(brightness)
                print(f"Ambient Light: {lux:.2f} lux, LED Brightness: {brightness:.2f}%")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        led.close()
        print("LED and resources released.")

if __name__ == "__main__":
    main()

