from gpiozero import OutputDevice, Servo
import time

# Constants for GPIO pins (BCM numbering)
LASER_PIN = 17
HORIZONTAL_SERVO_PIN = 18
VERTICAL_SERVO_PIN = 19

# Class to control the laser diode
class Laser:
    def __init__(self, pin):
        try:
            self.laser = OutputDevice(pin)
        except Exception as e:
            print(f"Error initializing laser: {e}")
            self.laser = None

    def on(self):
        if self.laser:
            try:
                self.laser.on()
            except Exception as e:
                print(f"Error turning laser on: {e}")

    def off(self):
        if self.laser:
            try:
                self.laser.off()
            except Exception as e:
                print(f"Error turning laser off: {e}")

    def close(self):
        if self.laser:
            try:
                self.laser.close()
            except Exception as e:
                print(f"Error closing laser: {e}")

# Class to control the servo motors
class Aim:
    def __init__(self, ld, sd):
        self.laser = Laser(LASER_PIN)
        self.horizontal = Servo(HORIZONTAL_SERVO_PIN)
        self.vertical = Servo(VERTICAL_SERVO_PIN)
        self.ld = ld  # Laser duration
        self.sd = sd  # Short delay
        self.hp = [0.05, 0.15, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 0.95] # Horizontal positions
        self.vp = [0.95, 0.85, 0.75, 0.65, 0.55, 0.45, 0.35, 0.25, 0.15, 0.05] # Vertical positions

    def aim(self, nums):
        try:
            for b in sorted(nums):
                print(f"Target {b} in {self.hp[b-1], self.vp[b-1]}")
                self.move((self.hp[b-1], self.vp[b-1]))
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self.move((0.5, 0.5)) # Return to center
            self.laser.off()
        except KeyboardInterrupt:
            print("Stopped by user")
        except Exception as e:
            print(f"An error occurred: {e}")

    def move(self, pos):
        hx, vy = pos
        self.horizontal.value = hx
        self.vertical.value = vy
