# radiation_monitor.py
# Reads radiation data from a UART sensor and triggers an alarm if levels are high.
# Target: Raspberry Pi 3 Model B+

import serial
import time
import RPi.GPIO as GPIO
from gpiozero import OutputDevice

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1  # seconds

def initialize_serial(port, baud):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    alarm = OutputDevice(pin)
    return alarm

def read_radiation_level(serial_connection):
    """Reads a radiation level from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Invalid data received from sensor.")
        return None

def check_and_trigger_alarm(radiation_value, alarm_device, threshold):
    """Checks if the radiation level exceeds the threshold and triggers the alarm."""
    if radiation_value is not None:
        if radiation_value > threshold:
            alarm_device.on()
            print(f"ALARM: Radiation level {radiation_value:.2f} µSv/h exceeds threshold.")
        else:
            alarm_device.off()
        print(f"Radiation level: {radiation_value:.2f} µSv/h")

def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE)
    if serial_connection is None:
        exit(1)

    alarm_device = initialize_gpio(ALARM_PIN)

    try:
        while True:
            radiation_level = read_radiation_level(serial_connection)
            check_and_trigger_alarm(radiation_level, alarm_device, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        alarm_device.close()
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

