import serial
import time
import pynmea2
import logging

# Configure logging
logging.basicConfig(filename='gps_coordinates_log.txt', level=logging.INFO,
                    format='%(asctime)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        logging.error(f"Error opening serial port: {e}")
        return None

def parse_gps_data(data):
    """Parses GPS data from NMEA sentence."""
    try:
        msg = pynmea2.parse(data)
        if hasattr(msg, 'latitude') and hasattr(msg, 'longitude') and hasattr(msg, 'altitude'):
            return msg.latitude, msg.longitude, msg.altitude
        else:
            return None, None, None
    except pynmea2.ParseError as e:
        logging.warning(f"NMEA Parse Error: {e}")
        return None, None, None
    except Exception as e:
        logging.error(f"Error parsing GPS data: {e}")
        return None, None, None

def log_coordinates(latitude, longitude, altitude):
    """Logs the GPS coordinates to a file."""
    if latitude is not None and longitude is not None and altitude is not None:
        log_message = f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}"
        logging.info(log_message)
        print(f"Logged: {log_message}")

def main():
    """Main function to read GPS data and log coordinates."""
    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if ser is None:
        print("Failed to initialize serial port. Exiting.")
        return

    try:
        while True:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line.startswith('$GPGGA'):
                    latitude, longitude, altitude = parse_gps_data(line)
                    if latitude is not None and longitude is not None and altitude is not None:
                        log_coordinates(latitude, longitude, altitude)
            except serial.SerialException as e:
                logging.error(f"Serial communication error: {e}")
                break
            except Exception as e:
                logging.error(f"An unexpected error occurred: {e}")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

