from flask import Flask, render_template, request, jsonify
import json
import serial
import time

# Initialize the Flask application
app = Flask(__name__)

# Define the serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Data store for our items
item_store = [{"id": 1, "name": "Work", "done": False}, {"id": 2, "name": "Home", "done": True}]

# Function to get the next item ID
def get_next_id():
    return item_store[-1]['id'] + 1 if item_store else 1

# Route to display item details
@app.route('/getset/<int:item_id>')
def get_item(item_id):
    item = next((item for item in item_store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    return jsonify({"error": "Item not found"}), 404

# Route to display all items
@app.route('/getdata')
def get_all_items():
    return jsonify(item_store)

# Route to handle POST requests for new items
@app.route('/postjson', methods=['POST', 'GET'])
def handle_post():
    if request.method == 'POST':
        data = request.get_json() or request.form.to_dict()
        new_id = get_next_id()
        new_item = {
            "id": new_id,
            "name": data.get('name', ''),
            "done": data.get('done', '').lower() == 'true'
        }
        item_store.append(new_item)
        return jsonify(item_store)
    return jsonify(item_store)

# Route to display the index page
@app.route('/')
def index_page():
    return render_template('index.html')

# Route to get the instrument version
@app.route('/version')
def get_instrument_version():
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            ser.write(b'*IDN?\n')
            time.sleep(0.1)  # Give the instrument time to respond
            response = ser.read_all().decode('utf-8', errors='ignore').replace('\n', '<br>')
        return f"<html><body><pre>{response}</pre></body></html>"
    except serial.SerialException as e:
        return jsonify({"error": f"Serial communication error: {e}"}), 503
    except Exception as e:
        return jsonify({"error": f"An unexpected error occurred: {e}"}), 500

# Main execution block
if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

